    if not tokens:
        return
    pos = {}
    neg = {}
    other = []
    for t in tokens:
        c0 = t[0]
        if 49 <= c0 <= 57:
            n = len(t)
            if n in pos:
                pos[n].append(t)
            else:
                pos[n] = [t]
        elif c0 == 45 and len(t) > 1 and 49 <= t[1] <= 57:
            n = len(t)
            if n in neg:
                neg[n].append(t)
            else:
                neg[n] = [t]
        else:
            other.append(t)
    if other:
        # fallback or zero handling
        if all(t == b'0' for t in other):
            zeros = other
            other = []
        else:
            tokens.sort(key=int)
            os.write(1, b'\n'.join(tokens) + b'\n')
            return
    else:
        zeros = []
    out = []
