import sys, os

def main():
    tokens = sys.stdin.buffer.read().split()
    if not tokens:
        return
    # Pre-allocate buckets for lengths up to 22
    pos = [[] for _ in range(24)]
    neg = [[] for _ in range(24)]
    zeros = []
    fallback = False
    for t in tokens:
        c0 = t[0]
        n = len(t)
        if 49 <= c0 <= 57 and n < 24:
            pos[n].append(t)
        elif c0 == 45 and 1 < n < 24 and 49 <= t[1] <= 57:
            neg[n].append(t)
        elif t == b'0':
            zeros.append(t)
        else:
            fallback = True
            break
    if fallback:
        tokens.sort(key=int)
        os.write(1, b'\n'.join(tokens) + b'\n')
        return
    out = []
    for n in range(23, 1, -1):
        b = neg[n]
        if b:
            b.sort(reverse=True)
            out.extend(b)
    if zeros:
        out.extend(zeros)
    for n in range(1, 24):
        b = pos[n]
        if b:
            b.sort()
            out.extend(b)
    os.write(1, b'\n'.join(out) + b'\n')

if __name__ == '__main__':
    main()
